def longest_unique_substring(s: str) -> int:
    """Length of the longest substring without repeating characters. 0 <= len(s) <= 10^5.
    >>> longest_unique_substring("abcabcbb")
    3
    >>> longest_unique_substring("pwwkew")
    3
    """
    if not s:
        return 0

    last_seen = {}
    start = 0
    max_len = 0

    for i, char in enumerate(s):
        if char in last_seen and last_seen[char] >= start:
            start = last_seen[char] + 1
        last_seen[char] = i
        current_len = i - start + 1
        if current_len > max_len:
            max_len = current_len

    return max_len

def valid_brackets(s: str) -> bool:
    """True if every bracket in s is closed in the right order. s contains only ()[]{} characters.
    >>> valid_brackets("()[]{}")
    True
    >>> valid_brackets("(]")
    False
    """
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set('([{')

    for ch in s:
        if ch in opening:
            stack.append(ch)
        else:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()

    return len(stack) == 0

def lis_length(nums: list[int]) -> int:
    """Length of the longest strictly increasing subsequence. 0 <= len(nums) <= 10^5.
    >>> lis_length([10, 9, 2, 5, 3, 7, 101, 18])
    4
    >>> lis_length([0, 1, 0, 3, 2, 3])
    4
    """
    import bisect

    if not nums:
        return 0

    tails = []
    for num in nums:
        # Find the leftmost element in tails that is >= num
        # For strictly increasing, we replace the first element >= num
        idx = bisect.bisect_left(tails, num)
        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num

    return len(tails)
